using Ashen.Core;
using System.Text.Json;
using System.Text.Json.Nodes;
static class UpperMall25Tests
{
 public static void Run(Action<bool,string> check,bool route=true)
 {
  var production=CampaignLoader.Load(CampaignLoader.BundledUpper18Path);check(production.SchemaVersion==23&&production.Areas.Count==77&&production.LowerMall!.Sites.Count==72,"Phase 25 complete lower54 plus upper18 campaign loads with independent area identities");
  check(production.LowerMall!.Sites.Where(s=>s.Level=="upper").Select(s=>s.DisplayNumber).SequenceEqual(Enumerable.Range(1,18)),"Phase 25 upper display numbering remains 1–18 while progress keys cannot collide with lower stores");
  var original=CampaignLoader.Load(CampaignLoader.BundledLower54Path);check(original.LowerMall!.Sites.All(s=>JsonSerializer.Serialize(s)==JsonSerializer.Serialize(production.LowerMall.Sites.Single(x=>x.Number==s.Number))),"Phase 25 all 54 earlier shop definitions remain unchanged");
  check(production.LowerMall.Sites.Where(s=>s.Level=="upper").All(s=>s.BookText.Length>3000&&s.Source.PageStart>=333&&s.Source.PageEnd<=362),"Phase 25 full upper source entries and exact audit page ranges retained");
  string path=Path.Combine(Path.GetTempPath(),"zombie-upper25-"+Guid.NewGuid()+".json");
  World Fixture(int n,int? entry=null)
  {
   var c=CampaignLoader.Clone(production);var site=c.LowerMall!.Sites.Single(s=>s.Number==100+n);var start=c.Areas.Single(a=>a.Id==site.AreaId);var origin=c.Areas.Single(a=>a.Id==c.StartAreaId);var party=origin.Actors.Where(p=>!c.Actors.Single(a=>a.Id==p.ActorId).Enemy&&!c.Actors.Single(a=>a.Id==p.ActorId).Recruitable).ToArray();origin.Actors.RemoveAll(p=>party.Contains(p));int i=0;foreach(var p in party){p.Position=new(8+i++,26);start.Actors.Add(p);}c.StartAreaId=start.Id;
   if(entry.HasValue){var chosen=site.Encounters.Single(e=>e.Low==entry);site.Encounters=[new(){Low=1,High=6,EncounterId=chosen.EncounterId,Text=chosen.Text,Dice=chosen.Dice,Die=chosen.Die,Bonus=chosen.Bonus}];}
   return World.New(c);
  }
  void Clear(World w){w.Mode=Mode.Explore;w.Order.Clear();foreach(var p in w.Party){p.Hp=p.MaxHp;p.Character.SetCondition("unconscious","Unconscious",false);}for(int i=0;i<3;i++)foreach(var e in w.Actors.Where(a=>a.Enemy&&a.Alive).ToArray())w.ResolveCampaignHazard(e,1000,DamageType.Fire);foreach(var p in w.Party){p.Hp=p.MaxHp;p.Character.SetCondition("unconscious","Unconscious",false);}w.Mode=Mode.Explore;w.Order.Clear();}
  void Beside(World w,LowerMallAction a){w.StopAll();foreach(var f in w.Features.Where(f=>f.Kind=="door"))f.Used=true;w.PartyLeader.Pos=w.Features.Single(f=>f.Id==a.FeatureId).Pos;w.Reveal();}
  bool Do(World w,string effect){var a=w.CurrentLowerMallSite!.Actions.Single(a=>a.Effect==effect);Beside(w,a);for(int i=0;i<80;i++){if(w.LowerMallActionReason(w.PartyLeader,a.Id)!="")return false;if(w.PerformLowerMallAction(w.PartyLeader,a.Id))return true;}return false;}
  ItemStack Take(World w,int n,int slot){var f=w.Features.Single(f=>f.Id==$"feature.upper.{n:00}.loot.{slot}");var stack=f.Contents.Items.First();f.Contents.Items.Remove(stack);w.PartyLeader.Inventory.Add(stack);return w.PartyLeader.Inventory.FindInstance(stack.InstanceId)!;}
  for(int n=1;n<=18;n++)
  {
   var w=Fixture(n);var d=w.CurrentLowerMallSite!;var s=w.LowerMallProgress(100+n)!;check(d.Level=="upper"&&d.DisplayNumber==n&&w.LowerMallProgress(n)==null,"Phase 25 upper "+n+" uses isolated persistent identity");
   var captures=Environment.GetEnvironmentVariable("ZOMBIE_MALL_PHASE25_CAPTURE_DIR");if(!string.IsNullOrWhiteSpace(captures)&&n is 1 or 4 or 5 or 7 or 8 or 11 or 15 or 17 or 18){Directory.CreateDirectory(captures);w.Save(Path.Combine(captures,$"upper-{n:00}.json"));}
   var hazard=d.Actions.Single(a=>a.Id==s.HazardId);Beside(w,hazard);var before=JsonSerializer.Serialize(w);w.LowerMallActionReason(w.PartyLeader,hazard.Id);check(before==JsonSerializer.Serialize(w),"Phase 25 upper "+n+" action preview cannot roll, spend, spawn or award");
   if(!s.HazardResolved)check(w.PerformLowerMallAction(w.PartyLeader,hazard.Id),"Phase 25 upper "+n+" resolves its saved source hazard");Clear(w);
   var cache=d.Actions.First(a=>a.Kind=="loot"&&a.Dc==0&&a.RequiredActionId=="");Beside(w,cache);var f=w.Features.Single(f=>f.Id==cache.FeatureId);check(w.TakeAllContainer(w.PartyLeader,f)==0,"Phase 25 upper "+n+" source cache requires physical search");check(w.PerformLowerMallAction(w.PartyLeader,cache.Id)&&w.TakeAllContainer(w.PartyLeader,f)>0&&!w.PerformLowerMallAction(w.PartyLeader,cache.Id),"Phase 25 upper "+n+" finite source goods transfer once without loot rerolls");
   var back=d.Actions.Single(a=>a.Effect=="upper-back");Beside(w,back);check(w.PerformLowerMallAction(w.PartyLeader,back.Id),"Phase 25 upper "+n+" back room has an explicit real investigation");Clear(w);
   if(s.Events.Contains("gas-active"))check(Do(w,"upper-fuel"),"Phase 25 leaking fuel must be isolated before securing");
   w.StopAll();w.PartyLeader.Pos=w.Features.Single(f=>f.Id==$"feature.{d.Prefix}.secure").Pos;w.Reveal();int xp=w.LowerMallXpAwarded+w.LowerMallXpRemainder;check(w.SecureLowerMall(w.PartyLeader)&&s.Secured,"Phase 25 upper "+n+" secures only after its hazards and real threats are cleared");check(w.LowerMallXpAwarded+w.LowerMallXpRemainder==xp+d.SecureXp&&!w.SecureLowerMall(w.PartyLeader),"Phase 25 upper "+n+" printed securing milestone is exact and cannot repeat");
   w.Save(path);var loaded=World.Load(path);check(loaded.LowerMallProgress(100+n)!.Secured&&loaded.LowerMallProgress(n)==null&&loaded.Features.Single(x=>x.Id==cache.FeatureId).Contents.Items.Count==0,"Phase 25 upper "+n+" reload keeps independent progress, emptied stock, corpses and secured flag");
  }
  var world=Fixture(5);check(world.Features.Single(f=>f.Id=="feature.upper.05.loot.2").Contents.Items.Single().Quantity is >=1 and <=6&&world.Features.Single(f=>f.Id=="feature.upper.05.loot.5").Contents.Items.Single().Quantity is >=1 and <=6,"Phase 25 deli meat and salt quantities use separate saved d6 rolls");Clear(world);check(!Do(world,"upper-freezer")&&Do(world,"upper-power")&&Do(world,"upper-freezer"),"Phase 25 deli locker requires restored power before its source lock check");
  world=Fixture(4);Clear(world);check(Do(world,"upper-back"),"Phase 25 Hartley is physically released by exam-room investigation");var hartley=world.Actors.Single(a=>a.Name=="Dr. Lyle Hartley");check(hartley.Hp==28&&hartley.Ac==13&&hartley.AttackBonus==4&&hartley.Die==6,"Phase 25 Hartley uses printed HP, AC and scalpel attack");check(Do(world,"upper-shiny")&&hartley.Character.HasCondition("stunned"),"Phase 25 reflective distraction actually stuns Hartley");
  world=Fixture(6,6);var eye=world.Actors.Single(a=>a.Name=="Eye Horror");eye.Character.SetCondition("blinded","Blind",true);check(!eye.Character.HasCondition("blinded")&&eye.MaxHp==22&&eye.Ac==15,"Phase 25 Eye Horror has printed defenses and real blindness immunity");
  world=Fixture(7,4);var stat=world.Actors.Single(a=>a.Name=="Static Shambler");int hp=stat.Hp;world.ResolveCampaignHazard(stat,10,DamageType.Lightning);check(stat.Hp==hp,"Phase 25 Static Shambler is mechanically immune to electrical hazards");
  var emp=Take(world,7,0);var hero=world.PartyLeader;check(world.UseOwnedItem(hero,emp.InstanceId)&&hero.Inventory.FindInstance(emp.InstanceId)==null,"Phase 25 finite EMP grenade consumes its physical charge");
  world=Fixture(15,1);var cyber=world.Actors.First(a=>a.Name.StartsWith("Tech Cyber-Zombie"));hp=cyber.Hp;world.ResolveCampaignHazard(cyber,8,DamageType.Lightning);check(cyber.Hp==hp-4,"Phase 25 Tech and Trends implants resist lightning damage");check(world.LowerMallProgress(115)!.StockRoll is >=1 and <=10,"Phase 25 rare experimental EMP uses one saved ten-percent roll");
  world=Fixture(18);var makeup=Take(world,18,1);hero=world.PartyLeader;int bonus=hero.SkillModifier(Skill.Persuasion);check(makeup.Charges==5&&world.UseOwnedItem(hero,makeup.InstanceId)&&makeup.Charges==4&&hero.SkillModifier(Skill.Persuasion)==bonus+1,"Phase 25 five-use makeup kit applies an actual one-day Charisma skill bonus");for(int hour=0;hour<24;hour++)world.AdvanceCampaignSeconds(3600);check(hero.SkillModifier(Skill.Persuasion)==bonus,"Phase 25 makeup bonus expires after the saved campaign day");var serum=Take(world,18,4);check(world.UseOwnedItem(hero,serum.InstanceId)&&hero.Character.HitPoints.Temporary==5,"Phase 25 anti-aging serum grants five actual temporary HP");
  world=Fixture(13);var vitamins=Take(world,13,1);hero=world.PartyLeader;check(world.UseOwnedItem(hero,vitamins.InstanceId)&&hero.Character.HasCondition("upper-vitamin"),"Phase 25 vitamins prepare one actual disease-save advantage");world.SurvivorSave(hero,Ability.Constitution,12,"infection");check(!hero.Character.HasCondition("upper-vitamin"),"Phase 25 the next disease save consumes vitamin protection");
  world=Fixture(9);var sticks=world.Features.Single(f=>f.Id=="feature.upper.09.loot.2").Contents.Items.Single();check(sticks.Quantity is >=2 and <=16,"Phase 25 music-store drumsticks roll the printed 2d8 stock range");
  world=Fixture(11);Clear(world);int machine=world.LowerMallProgress(111)!.BonusRoll;check(Do(world,"upper-machine")&&world.LowerMallProgress(111)!.Events.Contains("machine:"+machine)&&!Do(world,"upper-machine"),"Phase 25 ice cream machine resolves its persistent four-way branch once");
  world=Fixture(16);Clear(world);hero=world.PartyLeader;int ac=hero.Ac,speed=hero.EffectiveSpeedFeet;var boots=Take(world,16,2);check(hero.Ac==ac,"Phase 25 carrying steel-toed boots does not apply their worn bonus");check(world.Equip(hero,hero.Inventory.Items.FindIndex(i=>i.InstanceId==boots.InstanceId))&&hero.Ac==ac+1&&hero.EffectiveSpeedFeet==speed-5,"Phase 25 actually worn steel-toed boots trade five feet of movement for one AC");
  world=Fixture(8);hero=world.PartyLeader;var drink=Take(world,8,3);check(world.UseOwnedItem(hero,drink.InstanceId)&&hero.Inventory.FindInstance(drink.InstanceId)!.Quantity==5&&!world.UseOwnedItem(hero,drink.InstanceId),"Phase 25 one daily energy benefit consumes one can while retaining the other five");
  world=Fixture(6,6);hero=world.PartyLeader;eye=world.Actors.Single(a=>a.Name=="Eye Horror");hero.Pos=eye.Pos.Neighbors().First(p=>world.CanStand(p.Center,hero));world.Reveal();var laser=Take(world,6,11);hp=eye.Hp;check(world.UseOwnedItem(hero,laser.InstanceId)&&eye.Hp<hp&&hero.Inventory.FindInstance(laser.InstanceId)==null,"Phase 25 repaired optical laser deals its actual d4 fire shot and consumes the single device");
  world=Fixture(6,3);var stalker=world.Actors.Single(a=>a.Name=="Optical Stalker");check(stalker.Character.HasCondition("hidden")&&world.AttackModifiers(stalker,world.PartyLeader).Advantage,"Phase 25 source stalker ambush enters with actual attack advantage");
  world=Fixture(16,1);var cobbler=world.Actors.Single(a=>a.Name=="Zombie Cobbler");check(cobbler.Character.HasCondition("chapter-asleep"),"Phase 25 the source cobbler initially ignores the expedition");world.ResolveCampaignHazard(cobbler,1,DamageType.Fire);check(!cobbler.Character.HasCondition("chapter-asleep"),"Phase 25 disturbing the cobbler by damage actually wakes it");
  world=World.New(original);world.Save(path);var legacy=JsonNode.Parse(File.ReadAllText(path))!;legacy["Version"]=37;File.WriteAllText(path,legacy.ToJsonString());var migrated=World.Load(path);check(migrated.Version==World.CurrentSaveVersion&&migrated.Campaign!.LowerMall!.Sites.Count==54,"Phase 25 v37 migration preserves the embedded lower54 campaign rather than injecting new maps");
  world=Fixture(18);world.Save(path);var saved=File.ReadAllText(path);void Reject(Action<JsonNode> change,string why){var node=JsonNode.Parse(saved)!;change(node);File.WriteAllText(path,node.ToJsonString());bool reject=false;try{World.Load(path);}catch(InvalidDataException){reject=true;}check(reject,"Phase 25 rejects "+why);}
  Reject(n=>n["LowerMallStates"]![0]!["Number"]=18,"upper progress reassigned to a lower shop");Reject(n=>n["LowerMallXpAwarded"]=250,"unearned source XP");File.Delete(path);
  if(route)ExpeditionTests.RunFullRoute(check,CampaignLoader.BundledUpper18Path,true,false,true,true,true,true,true,true,true,true,true);
 }
}
